def prider(i):
    """extra Pindi riders for the swarm: dark kameez / jackets, never Waleed's teal"""
    r=random.Random(900+i*17); top=r.choice(['#17181E','#3A2A22','#27365A','#5A1522','#4A4E5A','#6B7A4A','#8A5A36','#C9B48A','#F4F1EA','#2B4A7A']); c=dict(skin=r.choice(SKL),hair=r.choice(HRL),eye='#2A1A12',
        top=top,trim=shade(top,.75),hairstyle=r.choice(['quiff','short','fringe','curly','cap','neat']),cap=r.choice(['#16171C','#C8372D','#F4F1EA']),h=r.choice([.95,1.0,1.04,1.08]),wide=r.choice([.92,1.0,1.08]))
    if r.random()<.55: c.update(kurta=True,shalwar=True,pants=top,sandals='#5A3A22')
    else: c.update(pants=r.choice(['#1C1D24','#2B4A7A','#3A3D47']),shoes=r.choice(['#F4F5FA','#22242B']),sole='#F0F1F5',accent='#22242B'); c.update(jacket=r.choice(['#2A2C34','#3A2A22','#5A1522','#3A5F92'])) if r.random()<.5 else None
